/* Advanced4 — hybrid networking: VPN first, Direct Connect later, Transit Gateway segmentation and hybrid DNS. */
(function(){
 const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x));
 const canon=v=>Array.isArray(v)?v.map(canon):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canon(v[k])])):v;
 const same=(a,b)=>JSON.stringify(canon(a))===JSON.stringify(canon(b));
 const ACCT='333333333333',R='ap-south-1',TGW='tgw-0shop0000000001',CGW='cgw-0godam00000001',ONPREM='192.168.10.0/24';
 const A_PROD='tgw-attach-0prod000001',A_DEV='tgw-attach-0dev0000001',A_SHARED='tgw-attach-0shared0001',A_VPN='tgw-attach-00000000000000001',VPN='vpn-00000000000000001';
 const RT_PROD='tgw-rtb-0prod000001',RT_DEV='tgw-rtb-0dev0000001',RT_SHARED='tgw-rtb-0shared0001',RT_ONPREM='tgw-rtb-0onprem0001';
 const VPC={prod:{id:'vpc-0prod0000000001',cidr:'10.10.0.0/16'},dev:{id:'vpc-0dev00000000001',cidr:'10.20.0.0/16'},shared:{id:'vpc-0shared00000001',cidr:'10.30.0.0/16'}};
 const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
 function seed(stage='main'){
  const att=(id,k)=>({id,type:'vpc',resourceId:VPC[k].id,name:k,state:'available',cidrs:[VPC[k].cidr]});
  const a={region:R,hybridMode:true,hybridRevision:1,callerIdentity:{Account:ACCT,Arn:`arn:aws:iam::${ACCT}:role/network-operator`,UserId:'TRAINING'},
   tgw:{id:TGW,asn:64512,description:'ShopKaro hub (Mumbai)'},
   onPrem:{name:'GodamTech Bhiwandi DC',asn:65010,publicIp:'203.0.113.10',network:ONPREM,advertised:[ONPREM],configured:true},
   tgwAttachments:[att(A_PROD,'prod'),att(A_DEV,'dev'),att(A_SHARED,'shared')],
   tgwRouteTables:[{id:RT_PROD,name:'rt-prod',associations:[A_PROD],propagations:[A_SHARED],statics:[]},{id:RT_SHARED,name:'rt-shared',associations:[A_SHARED],propagations:[A_PROD,A_DEV],statics:[]},{id:RT_DEV,name:'rt-dev',associations:[A_DEV],propagations:[A_SHARED],statics:[{cidr:VPC.prod.cidr,attachmentId:null}]},{id:RT_ONPREM,name:'rt-onprem',associations:[],propagations:[],statics:[]}],
   customerGateways:[{id:CGW,bgpAsn:65010,ip:'203.0.113.10',type:'ipsec.1',state:'available',device:'godam-bhiwandi-fw'}],vpnConnections:[],
   vpcs:Object.entries(VPC).map(([k,v])=>({id:v.id,cidr:v.cidr,name:'shop-'+k,default:false})),subnets:[],securityGroups:[],instances:[],buckets:[]};
  if(stage!=='main'){
   a.vpnConnections.push({id:VPN,cgwId:CGW,tgwId:TGW,type:'ipsec.1',state:'available',staticRoutesOnly:false,attachmentId:A_VPN,tunnels:[{outside:'13.234.200.12'},{outside:'13.234.200.13'}]});
   a.tgwAttachments.push({id:A_VPN,type:'vpn',resourceId:VPN,name:'vpn-godam-bhiwandi-fw',state:'available',cidrs:[ONPREM],probeCidr:ONPREM});a.hybridVpnSeq=1;
   const t=id=>a.tgwRouteTables.find(x=>x.id===id);t(RT_ONPREM).associations=[A_VPN];t(RT_ONPREM).propagations=[A_PROD,A_SHARED];t(RT_PROD).propagations.push(A_VPN);t(RT_SHARED).propagations.push(A_VPN);a.hybridRevision=9;
  }
  if(stage==='broken'){const t=id=>a.tgwRouteTables.find(x=>x.id===id);t(RT_DEV).associations=[];t(RT_SHARED).associations.push(A_DEV);t(RT_PROD).propagations.push(A_DEV);}
  return a;
 }
 const initial=seed(),ready=seed('ready');
 const rt=(a,id)=>(a.tgwRouteTables||[]).find(t=>t.id===id);
 const open=(a,x,y)=>AG.hybridRoundTrip(a,x,y);
 const closed=(a,x,y)=>{const ip=c=>{const m=c.split('/')[0].split('.').map(Number);return ((m[0]*256+m[1])*256+m[2])*256+m[3]+10;};const at=id=>(a.tgwAttachments||[]).find(z=>z.id===id);const cx=at(x),cy=at(y);if(!cx||!cy)return true;const go=AG.hybridHop(a,x,ip(cy.probeCidr||cy.cidrs[0])),back=AG.hybridHop(a,y,ip(cx.probeCidr||cx.cidrs[0]));return !(go.ok&&go.to===y)&&!(back.ok&&back.to===x);};
 const vpnAtt=a=>{const v=(a.vpnConnections||[]).filter(v=>v.state!=='deleted');return v.length===1&&v[0].cgwId===CGW&&v[0].tgwId===TGW&&v[0].state==='available'?v[0].attachmentId:null;};
 function coreKept(s){const a=s.account;return a.hybridMode===true&&same(a.tgw,initial.tgw)&&same(a.onPrem,initial.onPrem)&&same(a.customerGateways,initial.customerGateways)&&same(a.callerIdentity,initial.callerIdentity)&&same(a.vpcs,initial.vpcs)&&same((a.tgwAttachments||[]).filter(x=>x.type==='vpc'),initial.tgwAttachments)&&(a.tgwRouteTables||[]).length===4&&[RT_PROD,RT_SHARED,RT_DEV,RT_ONPREM].every(id=>!!rt(a,id));}
 function segmentation(a){return open(a,A_PROD,A_SHARED)&&open(a,A_DEV,A_SHARED)&&closed(a,A_DEV,A_PROD)&&same(rt(a,RT_PROD).associations,[A_PROD])&&same(rt(a,RT_SHARED).associations,[A_SHARED])&&same(rt(a,RT_DEV).associations,[A_DEV])&&rt(a,RT_DEV).propagations.includes(A_SHARED)&&(rt(a,RT_DEV).statics||[]).some(r=>r.cidr===VPC.prod.cidr&&!r.attachmentId);}
 function onprem(a){const v=vpnAtt(a);return !!v&&same(rt(a,RT_ONPREM).associations,[v])&&open(a,v,A_PROD)&&open(a,v,A_SHARED)&&closed(a,v,A_DEV);}
 const readOf=(a,id)=>(a.hybridReads||[]).some(r=>r.revision===(a.hybridRevision||0)&&r.table===id);
 const tasks=[
  {text:'TGW, VPC attachments, CGW aur chaar route tables original; prod/dev/shared segmentation intact (dev ↛ prod, dono ↔ shared)',check:s=>coreKept(s)&&segmentation(s.account)},
  {text:'GodamTech VPN (dynamic/BGP ya static) available aur sirf rt-onprem se associated',check:s=>{const v=vpnAtt(s.account);return !!v&&same(rt(s.account,RT_ONPREM).associations,[v]);}},
  {text:'On-prem ↔ prod aur on-prem ↔ shared dono taraf routes; on-prem ↔ dev band',check:s=>onprem(s.account)},
  {text:'rt-onprem ke routes current state mein padhe gaye',check:s=>onprem(s.account)&&readOf(s.account,RT_ONPREM)}
 ];
 const solution=[
  `aws ec2 create-vpn-connection --customer-gateway-id ${CGW} --transit-gateway-id ${TGW} --type ipsec.1`,
  `aws ec2 wait vpn-connection-available --vpn-connection-ids ${VPN}`,
  `aws ec2 associate-transit-gateway-route-table --transit-gateway-route-table-id ${RT_ONPREM} --transit-gateway-attachment-id ${A_VPN}`,
  `aws ec2 enable-transit-gateway-route-table-propagation --transit-gateway-route-table-id ${RT_ONPREM} --transit-gateway-attachment-id ${A_PROD}`,
  `aws ec2 enable-transit-gateway-route-table-propagation --transit-gateway-route-table-id ${RT_ONPREM} --transit-gateway-attachment-id ${A_SHARED}`,
  `aws ec2 enable-transit-gateway-route-table-propagation --transit-gateway-route-table-id ${RT_PROD} --transit-gateway-attachment-id ${A_VPN}`,
  `aws ec2 enable-transit-gateway-route-table-propagation --transit-gateway-route-table-id ${RT_SHARED} --transit-gateway-attachment-id ${A_VPN}`,
  `aws ec2 search-transit-gateway-routes --transit-gateway-route-table-id ${RT_ONPREM} --filters Name=state,Values=active`
 ];
 const itasks=[
  {text:'VPN, on-prem routes, TGW aur VPC attachments drill ke dauran unchanged',check:s=>coreKept(s)&&same(s.account.vpnConnections,ready.vpnConnections)&&same(rt(s.account,RT_ONPREM),rt(ready,RT_ONPREM))},
  {text:'Dev wapas rt-dev par; dev ↛ prod dono directions; prod ↔ shared, dev ↔ shared, on-prem ↔ prod/shared chalu',check:s=>segmentation(s.account)&&onprem(s.account)},
  {text:'rt-dev ke routes (active + blackhole) current state mein padhe gaye',check:s=>segmentation(s.account)&&readOf(s.account,RT_DEV)}
 ];
 const isolution=[`aws ec2 disable-transit-gateway-route-table-propagation --transit-gateway-route-table-id ${RT_PROD} --transit-gateway-attachment-id ${A_DEV}`,`aws ec2 disassociate-transit-gateway-route-table --transit-gateway-route-table-id ${RT_SHARED} --transit-gateway-attachment-id ${A_DEV}`,`aws ec2 associate-transit-gateway-route-table --transit-gateway-route-table-id ${RT_DEV} --transit-gateway-attachment-id ${A_DEV}`,`aws ec2 search-transit-gateway-routes --transit-gateway-route-table-id ${RT_DEV} --filters Name=state,Values=active,blackhole`];
 /* Planner: declared course assumptions (fictional monthly ₹ quotes, planning weeks), not AWS prices or SLAs. */
 const NOW=[{label:'Kuch nahi — DX ka intezaar',ready:false,gbps:0,enc:false,cost:0},{label:'1 VPN, static routes',ready:true,gbps:1.25,enc:true,cost:3500},{label:'2 VPN connections + BGP (ECMP)',ready:true,gbps:5,enc:true,cost:7000},{label:'Dedicated DX abhi order',ready:false,gbps:10,enc:false,cost:0}];
 const LATER=[{label:'VPN hi chalne do',gbps:5,consistent:false,resilient:true,dx:false,cost:0},{label:'Hosted DX 2 Gbps',gbps:2,consistent:true,resilient:false,dx:true,cost:45000},{label:'Dedicated 10G DX + VPN backup',gbps:10,consistent:true,resilient:true,dx:true,cost:120000},{label:'2 dedicated DX, 2 locations',gbps:20,consistent:true,resilient:true,dx:true,cost:260000}];
 const BUDGET=170000,inr=n=>'₹'+n.toLocaleString('en-IN');
 function planner(k){
  const n=NOW[k.now],l=LATER[k.later],enc=k.encrypt===1,dns=k.dns===1,seg=k.segment===1;
  const week3=n.ready&&n.gbps>=2&&n.enc,laterEnc=l.dx?enc:true,month4=l.gbps>=5&&l.consistent&&l.resilient&&laterEnc;
  const cost=n.cost+l.cost+(enc&&l.dx?6000:0)+(dns?28000:0)+(seg?3000:0);
  const fails=[];if(!n.ready)fails.push('week 3 tak link ready nahi (DX ko hafte lagte hain)');else if(n.gbps<2)fails.push('week 3: '+n.gbps+' Gbps < 2 Gbps');if(n.ready&&!n.enc)fails.push('week 3 link encrypted nahi');if(l.gbps<5)fails.push('month 4: '+l.gbps+' Gbps < 5 Gbps');if(!l.consistent)fails.push('month 4: internet par consistent bandwidth ka bharosa nahi');if(!l.resilient)fails.push('month 4: ek link gira toh connectivity khatam');if(l.dx&&!enc)fails.push('DX default encrypted nahi');if(!dns)fails.push('hybrid DNS nahi');if(!seg)fails.push('flat TGW table: dev bhi on-prem/prod tak');if(cost>BUDGET)fails.push('budget '+inr(BUDGET)+' se zyada');
  return {week3,month4,cost,fails,ok:!fails.length};
 }
 const VIS_NODES=[N('ec2',165,95,{label:'orders API'}),N('r53',500,95,{label:'Resolver inbound'}),N('ec2#dev',835,95,{label:'dev apps'}),N('tgw',500,265,{label:'Transit GW'}),N('rt',800,265,{label:'rt-onprem'}),N('onprem',175,435,{label:'Warehouse'}),N('vpn',500,435,{label:'VPN tunnels'})];
 const VIS_EDGES=[{from:'onprem',to:'vpn'},{from:'vpn',to:'tgw'},{from:'tgw',to:'ec2'},{from:'tgw',to:'r53'},{from:'tgw',to:'ec2#dev',dashed:true},{from:'tgw',to:'rt',dashed:true}];
 const VIS_GROUPS=[{label:'prod VPC 10.10.0.0/16',x:10,y:20,w:310,h:150,kind:'vpc'},{label:'shared VPC 10.30.0.0/16',x:345,y:20,w:310,h:150,kind:'vpc'},{label:'dev VPC 10.20.0.0/16',x:680,y:20,w:310,h:150,kind:'vpc'},{label:'Bhiwandi DC 192.168.10.0/24',x:10,y:360,w:330,h:150,kind:'onprem'}];
 AG.registerLevels('advanced',[{
  id:'advnet',icon:'🔗',title:'Hybrid Networking — VPN, Direct Connect aur Transit Gateway',badge:'Network Netritva',
  objectives:['Deadline aur bandwidth se VPN vs Direct Connect ka faisla lena','Transit Gateway route tables se segmentation banana (association vs propagation, return path)','Hybrid DNS (Resolver inbound/outbound) aur on-prem se private AWS access samajhna','DX resiliency, encryption aur inspection ke trade-offs pehchanna'],
  hook:{when:'ShopKaro course story — fictional',title:'GodamTech khareeda — par GodamTech ka data center Bhiwandi mein hai',text:'ShopKaro ne warehouse company GodamTech acquire ki. GodamTech ka inventory system Bhiwandi ke apne data center mein chalta hai. CFO ka order: teen hafte mein warehouse stock ShopKaro ke orders API se sync ho. Direct Connect ka order diya, par circuit aane mein hafte lagenge. Upar se ShopKaro ke paas pehle se prod, dev aur shared VPCs hain — dev kabhi prod tak nahi pahunchna chahiye.',mission:'Pehle Site-to-Site VPN se GodamTech ko Transit Gateway par jodo, sahi route tables ke saath. Phir ek segmentation bug theek karo. Simulator routing metadata check karta hai; IPsec, BGP aur asli packets yahan nahi chalte.'},
  steps:[
   {q:'Teen hafte ki deadline — VPN pehle, Direct Connect baad mein kyun?',analogy:'Naya ghar mila par pipeline connection mein hafte lagenge. Tab tak tanker se paani mangwaate ho — turant, thoda mehnga-unpredictable. Pipeline aate hi tanker backup ban jaata hai.',body:'<p><b>Site-to-Site VPN</b> internet ke upar IPsec encrypted tunnel hai. Har VPN connection mein <b>2 tunnels</b> hote hain (alag AWS endpoints). Setup din mein ho jaata hai. <b>Direct Connect (DX)</b> ek private physical link hai; AWS port review mein 72 business hours tak lag sakte hain, phir LOA-CFA, phir provider cross-connect lagata hai — kul milakar hafte.</p><div class="tbl-wrap"><table class="review-table swipe-table"><tr><th></th><th>Site-to-Site VPN</th><th>Direct Connect</th></tr><tr><td>Kitni der</td><td>Din</td><td>Hafte (port + LOA-CFA + cross-connect)</td></tr><tr><td>Raasta</td><td>Internet, IPsec encrypted</td><td>Private line, default encryption nahi</td></tr><tr><td>Bandwidth</td><td>Standard tunnel up to 1.25 Gbps</td><td>Dedicated 1/10/100/400 Gbps</td></tr><tr><td>Bharosa</td><td>Internet weather par depend</td><td>Consistent latency</td></tr></table></div><p class="dd-scroll-hint">👉 Phone par table ko side mein scroll karo.</p>',points:['VPN bandwidth: standard tunnel up to 1.25 Gbps; large-bandwidth tunnel option up to 5 Gbps. Transit Gateway par BGP (dynamic routing) ke saath ECMP se kai tunnels jodkar zyada bandwidth milti hai — static routing par ECMP nahi.','Kharch (approx, AWS Ohio example): VPN connection $0.05/hour ≈ ₹3,200/month + data transfer.','DX aane ke baad VPN band mat karo — sasta backup path ban jaata hai.','Hands-on: planner mein "now" aur "later" link alag chuno.'],asli:'Deadline paas hai toh VPN se shuru karo; DX tab tak primary nahi jab tak circuit asli mein test na ho.'},
   {q:'Direct Connect ke hisse — connection, VIF, DX gateway?',analogy:'DX location ek railway junction hai. Cross-connect = tumhari patri ka junction se jodna. VIF = us patri par alag-alag train services (private, public, transit).',body:'<p><b>Dedicated connection</b>: ek customer ka physical port — 1, 10, 100 ya 400 Gbps; port speed baad mein badal nahi sakti. <b>Hosted connection</b>: AWS Direct Connect Partner provision karta hai — 50 Mbps se 25 Gbps tak. Billing port active hone par ya LOA issue ke 90 din baad (jo pehle) shuru hoti hai.</p><p><b>VIF types:</b> private VIF (VPC tak, VGW/DX gateway se), public VIF (AWS public endpoints jaise S3 public IPs), transit VIF (DX gateway → Transit Gateway). <b>DX gateway</b> global hota hai: ek DX se kai Regions ke TGWs/VGWs tak.</p>',points:['ShopKaro design: transit VIF → DX gateway → Mumbai TGW. Hyderabad TGW bhi wahi DX gateway use kar sakta hai.','Hosted connection par AWS traffic policing karta hai: limit se upar burst drop hota hai.','DX private hai, par encrypted nahi. Encryption chahiye toh select dedicated ports par MACsec, ya DX ke upar IPsec VPN.','Hands-on: order game mein DX setup ke steps lagao.'],asli:'DX bandwidth aur consistency deta hai; encryption aur redundancy tumhe alag se design karni padti hai.'},
   {q:'Ek DX kaafi hai? Resiliency models kaise padhein?',analogy:'Ek hi pul se sheher jodo toh pul tootte hi sheher kat jaata hai. Do pul, alag jagah — tab asli bharosa.',body:'<div class="tbl-wrap"><table class="review-table swipe-table"><tr><th>Model</th><th>Kya bachata hai</th><th>Kab</th></tr><tr><td>Single DX</td><td>Kuch nahi — single point of failure</td><td>Sirf non-critical</td></tr><tr><td>DX + VPN backup</td><td>DX gire toh VPN (kam bandwidth)</td><td>Sasta, degraded chal jaaye</td></tr><tr><td>2 connections, 1 location</td><td>Device/port failure</td><td>Location fail hone ka risk accept</td></tr><tr><td>Connections 2 alag locations par</td><td>Location failure bhi</td><td>Critical workloads (high/maximum resiliency)</td></tr></table></div><p class="dd-scroll-hint">👉 Phone par table ko side mein scroll karo.</p>',points:['AWS Direct Connect Resiliency Toolkit models ke hisaab se connections plan karne mein madad karta hai.','DX + VPN backup mein failover ke baad bandwidth gir jaati hai — business ko pehle batao.','Failover test karo: BGP routes sahi shift hote hain ya nahi.','Hands-on: planner mein "2 dedicated DX, 2 locations" ka kharch dekho.'],asli:'Resiliency ka level workload ki criticality se aata hai. Warehouse sync ke liye DX + VPN backup theek; payments ke liye do locations.'},
   {q:'Transit Gateway: association aur propagation mein farak kya hai?',analogy:'TGW ek railway junction hai, route tables alag platform boards. Association = "meri train kaunsa board padhegi" (ek hi board). Propagation = "mera station kis-kis board par likha jaaye" (kai boards).',body:'<p>Har attachment (VPC, VPN, DX gateway, peering) <b>exactly ek</b> route table se associate hota hai — wahi table us attachment se aane wale packets ka next hop decide karti hai. Ek attachment apne routes <b>kai</b> tables mein propagate kar sakta hai. Static routes bhi daal sakte ho, blackhole bhi.</p><p>Route choice: sabse specific prefix jeetta hai; same prefix par static route propagated route se pehle aata hai. VPC subnet route tables mein bhi TGW ki taraf route chahiye.</p>',points:['Kharch (approx, AWS Ohio example): $0.05 per attachment-hour ≈ ₹3,200/attachment/month + $0.02/GB processed.','Default route table association/propagation on ho toh har naya attachment sabse baat karta hai — segmentation ke liye default band karke apni tables banao.','Attachment ko doosri table par le jaana ho toh pehle disassociate, phir associate.','Hands-on: mission mein VPN attachment ko rt-onprem se associate karo.'],asli:'Association = "main kahan dekhun", propagation = "mujhe kaun dekhe". Dono samjhe bina TGW design mat karo.'},
   {q:'Segmentation: dev ko prod se kaise door rakhein?',analogy:'Society mein ek hi gate se sab aate hain, par har block ki entry list alag hai. Dev block ki list mein prod block ka naam hi nahi — aur ek "no entry" board bhi.',body:'<div class="tbl-wrap"><table class="review-table swipe-table"><tr><th>Table</th><th>Kaun associate</th><th>Kiske routes</th></tr><tr><td>rt-prod</td><td>prod</td><td>shared, on-prem</td></tr><tr><td>rt-dev</td><td>dev</td><td>shared + blackhole 10.10.0.0/16</td></tr><tr><td>rt-shared</td><td>shared</td><td>prod, dev, on-prem</td></tr><tr><td>rt-onprem</td><td>VPN (GodamTech)</td><td>prod, shared</td></tr></table></div><p class="dd-scroll-hint">👉 Phone par table ko side mein scroll karo.</p><p><b>Return path rule:</b> conversation tabhi chalti hai jab dono attachments ki tables mein ek-doosre ke routes hon. Request ek table se jaata hai, reply doosri table se aata hai.</p>',points:['Blackhole static route guardrail hai: koi galti se prod propagation on kar de, tab bhi static blackhole same prefix par jeetta hai.','Shared services table ko sab jaanna padta hai, warna replies wapas nahi jaate.','Galti jo sab karte hain: ek flat table jisme sab associate aur sab propagate — sab sabse baat karte hain.','Hands-on: triage aur interview mein yahi bug pakdo aur theek karo.'],asli:'Segmentation = sahi association + chuni hui propagation + blackhole guardrail. Security groups phir bhi tight rakho.'},
   {q:'Hybrid DNS — on-prem aur AWS ek doosre ke naam kaise samjhein?',analogy:'Do offices ke reception alag hain. Inbound endpoint = AWS office ka reception jo bahar wale ka sawal sunta hai. Outbound endpoint + rule = AWS reception jo "godam.local" ke sawal GodamTech reception ko bhejta hai.',body:'<p><b>Route 53 VPC Resolver</b> (pehle naam: Route 53 Resolver) har VPC mein VPC+2 address par jawab deta hai. <b>Inbound endpoint</b>: on-prem DNS se aayi queries VPC mein (private hosted zone jaise <code>orders.shopkaro.internal</code>). <b>Outbound endpoint</b> + <b>forwarding rule</b>: VPC se <code>godam.local</code> jaise on-prem domains ki queries on-prem DNS server ko. Rules VPCs se associate hote hain aur accounts mein share ho sakte hain.</p>',points:['Har endpoint ko kam se kam 2 IP addresses chahiye (alag subnets/AZs mein) — API minimum 2 maangti hai.','Endpoints usually shared-services VPC mein; baaki VPCs rule associations se use karte hain.','On-prem DNS server par conditional forwarder: shopkaro.internal → inbound endpoint IPs.','Hands-on: lab24 mein inbound/outbound endpoints aur rule association bante hain.'],asli:'Hard-coded IPs se hybrid DNS mat chalao. Naam kaam karein tabhi failover aur migration aasaan rehte hain.'},
   {q:'On-prem se S3 aur partner services private kaise use karein?',analogy:'Gateway endpoint society ke andar ka shortcut gate hai — sirf society ke residents use kar sakte hain. Bahar wale ko alag private entrance (interface endpoint) chahiye.',body:'<p>S3 <b>gateway endpoint</b> sirf us VPC ke andar se aaye traffic ke liye kaam karta hai — on-prem (VPN/DX), peered VPC ya TGW ke raaste se nahi. On-prem ke liye <b>S3 interface endpoint</b> (PrivateLink) banao: VPC mein private IP wala ENI jo VPN/DX se reachable hai.</p><p><b>PrivateLink</b> partners ke liye bhi: apni service ko NLB ke peeche "endpoint service" banao; consumer apne VPC mein interface endpoint banata hai. CIDRs overlap karein tab bhi chalta hai, kyunki poora network nahi judta.</p>',points:['Interface endpoint ka per-hour + per-GB kharch hota hai; gateway endpoint free hai par sirf VPC-internal.','Private DNS names on-prem tak pahunchane ke liye hybrid DNS chahiye.','Endpoint policies se access aur tight karo.','Hands-on: quiz mein on-prem → S3 ka sawal hai.'],asli:'Gateway endpoint = VPC ka andar ka raasta. On-prem ya partner ko private access chahiye toh interface endpoint / PrivateLink.'},
   {q:'Inspection aur kharch — central firewall kab lagayein?',analogy:'Har ghar ka apna guard rakhne se sasta hai society gate par ek trained guard aur CCTV — par sab traffic gate se guzarna chahiye.',body:'<p>Central <b>inspection VPC</b> mein AWS Network Firewall (managed) ya Gateway Load Balancer + third-party appliances. TGW route tables traffic ko inspection VPC se guzaarti hain; stateful inspection ke liye <b>appliance mode</b> symmetric path rakhta hai.</p><div class="tbl-wrap"><table class="review-table swipe-table"><tr><th>Item (approx/course)</th><th>Kharch</th></tr><tr><td>VPN connection (AWS Ohio example)</td><td>$0.05/hr ≈ ₹3,200/mo</td></tr><tr><td>TGW attachment (AWS Ohio example)</td><td>$0.05/hr ≈ ₹3,200/mo each</td></tr><tr><td>TGW data processing</td><td>$0.02/GB (1 TB ≈ ₹1,800)</td></tr><tr><td>DX</td><td>Port-hours + data transfer + partner circuit (quote lo)</td></tr></table></div><p class="dd-scroll-hint">👉 Phone par table ko side mein scroll karo.</p>',points:['Inspection har packet par processing kharch badhata hai — kaunsa traffic inspect karna hai, chuno.','2 VPCs, transitive zarurat nahi → VPC peering sasta aur simple; bahut VPCs + on-prem → TGW.','Kharch region aur traffic ke saath badalta hai; pricing page se current number lo.','Hands-on: planner budget ₹1,70,000/month hai.'],asli:'Hub-and-spoke design ka faayda tabhi hai jab routing tables, inspection aur kharch teeno saath plan hon.'}
  ],
  myth:[{myth:'Direct Connect private line hai, isliye encrypted bhi hai.',sach:'DX default encrypted nahi. Select dedicated ports par MACsec, ya DX ke upar IPsec VPN chahiye.'},{myth:'Ek VPN tunnel se 10 Gbps nikal jayega.',sach:'Standard tunnel up to 1.25 Gbps. Zyada ke liye BGP ke saath ECMP (kai tunnels/connections), large-bandwidth tunnel option, ya DX.'},{myth:'Transit Gateway lagate hi saare VPCs safe aur segmented ho jaate hain.',sach:'Flat ya default route table mein sab sabse baat karte hain. Alag tables, chuni hui propagation aur blackholes se segmentation banta hai.'},{myth:'S3 gateway endpoint se on-prem servers bhi S3 privately use kar lenge.',sach:'Gateway endpoint sirf VPC ke andar ke traffic ke liye. On-prem ke liye S3 interface endpoint (PrivateLink).'}],
  playbook:{title:'Deadline → link → hub → segments → DNS → test',use:['Jaldi + encrypted chahiye → Site-to-Site VPN (BGP).','Stable bandwidth + private → Direct Connect; VPN backup rakho.','Kai VPCs + on-prem → Transit Gateway with separate route tables.'],avoid:['Flat/default TGW table jisme prod aur dev dono.','DX ko encrypted maan lena.','Single DX critical workload ke liye.'],how:['Requirement likho: bandwidth, deadline, encryption, resiliency.','VPN pehle (2 tunnels, BGP), DX order parallel.','Route tables: association + propagation + blackhole guardrail; return path check.','Resolver inbound/outbound + rules; failover test.'],redflags:['Dev attachment shared table se associated.','Reply path ki table mein route missing.','On-prem S3 access gateway endpoint par tika.','DX failover kabhi test nahi hua.'],rule:'Har flow ke liye do sawal: source attachment ki table mein route hai? Destination ki table mein wapas route hai?'},
  exam:[{cue:'Connectivity kuch din mein, encrypted',pick:'AWS Site-to-Site VPN'},{cue:'Consistent private bandwidth, internet nahi',pick:'AWS Direct Connect'},{cue:'DX par encryption in transit',pick:'MACsec (select dedicated) ya VPN over DX'},{cue:'DX maximum resiliency',pick:'Do alag DX locations par connections'},{cue:'Bahut VPCs + on-prem, transitive routing',pick:'Transit Gateway'},{cue:'Ek DX se kai Regions',pick:'Direct Connect gateway (transit/private VIF)'},{cue:'On-prem ko AWS private DNS names',pick:'Route 53 Resolver inbound endpoint'},{cue:'AWS ko on-prem domain names',pick:'Resolver outbound endpoint + forwarding rule'},{cue:'On-prem se S3 privately',pick:'S3 interface endpoint (PrivateLink), gateway endpoint nahi'}],
  lesson:['<h3>Kab kya — hybrid picker</h3><div class="tbl-wrap"><table class="review-table swipe-table"><tr><th>Zarurat</th><th>Candidate</th><th>Dhyan rakho</th></tr><tr><td>Din mein encrypted link</td><td>Site-to-Site VPN</td><td>1.25 Gbps/tunnel; ECMP ke liye BGP</td></tr><tr><td>Stable bulk bandwidth</td><td>Direct Connect</td><td>Hafte lagte; encryption alag; redundancy alag</td></tr><tr><td>Kai VPCs + on-prem hub</td><td>Transit Gateway</td><td>Tables: association vs propagation, return path</td></tr><tr><td>2 VPCs, simple</td><td>VPC peering</td><td>Non-transitive; overlap nahi chalega</td></tr><tr><td>Hybrid DNS</td><td>Resolver inbound/outbound + rules</td><td>Har endpoint 2+ IPs</td></tr><tr><td>Partner ko private service</td><td>PrivateLink endpoint service (NLB)</td><td>Overlapping CIDRs bhi chalte</td></tr><tr><td>Central inspection</td><td>Network Firewall / GWLB inspection VPC</td><td>Appliance mode, processing kharch</td></tr></table></div><p>Phone par table sideways swipe karo.</p><p><b>Decision tree:</b> Deadline din mein? → VPN. Bandwidth stable aur bada? → DX (+ VPN backup ya do locations). VPCs bahut? → TGW + alag tables. Naam resolve karne hain? → Resolver endpoints. Bahar walon ko private service? → PrivateLink.</p>'],
  stages:[
   {type:'dryrun',title:'🧪 Warehouse se orders API tak — ek packet ka safar',intro:'Fictional GodamTech request. Har click ek routing decision dikhata hai. Dry run ek walkthrough hai; asli IPsec ya BGP nahi chal raha.',lesson:'Source attachment ki associated table aage ka raasta chunti hai; reply ke liye destination ki table mein wapas route chahiye. DNS ke liye Resolver endpoints. Dev ka raasta blackhole par rukta hai.',goal:'Ek request aur request ka reply route tables ke through follow karo; teen faisle khud lo.',nodes:VIS_NODES,edges:VIS_EDGES,groups:VIS_GROUPS,panels:[{id:'rt',title:'Route table decision'},{id:'why',title:'Kyun'}],steps:[
    {say:'Warehouse server 192.168.10.5 orders API (10.10.4.20:443) ko call karta hai. GodamTech ka router (customer gateway) packet ko IPsec tunnel mein encrypt karke AWS bhejta hai.',flows:[{from:'onprem',to:'vpn',label:'IPsec',tone:'ok'}],nodes:{onprem:{tone:'ok',badge:'192.168.10.5'},vpn:{tone:'ok',badge:'2 tunnels UP'}},panels:{rt:['Abhi: on-prem router → VPN tunnel'],why:['VPN connection = 2 tunnels, alag AWS endpoints']}},
    {say:'Packet VPN attachment se Transit Gateway par aata hai. TGW ko next hop chunna hai.',flows:[{from:'vpn',to:'tgw',tone:'ok'}],nodes:{tgw:{tone:'busy',badge:'kaunsi table?'}},panels:{rt:['Source = VPN attachment'],why:['Har attachment exactly ek table se associate']},ask:Q('Is packet ka next hop kaunsi route table decide karti hai?','VPN attachment ki associated table — rt-onprem, kyunki source attachment ki table hi decide karti hai',['Prod VPC attachment ki table — rt-prod, kyunki destination ki table hamesha forward hop chunti hai','TGW ki saari tables ek saath merge hoti hain, aur jo route sabse pehle bana tha wahi chuna jaata hai','Koi table nahi — TGW har packet ko har attachment par broadcast karta hai aur sahi VPC packet le leta hai'],0,'Forward hop source attachment ki associated table se: VPN attachment → rt-onprem. Tables merge nahi hoti aur TGW broadcast nahi karta; destination ki table reply ke waqt kaam aati hai.')},
    {say:'rt-onprem mein 10.10.0.0/16 → prod attachment (propagated) milta hai. Packet prod VPC mein jaata hai. Subnet route table mein 192.168.0.0/16 → TGW hai aur security group 443 ko 192.168.10.0/24 se allow karta hai.',flows:[{from:'tgw',to:'ec2',label:'orders',tone:'ok'}],nodes:{ec2:{tone:'ok',badge:'request aaya'},rt:{tone:'acc',badge:'10.10/16 → prod'}},panels:{rt:['rt-onprem: 10.10.0.0/16 → prod (propagated)'],why:['Longest prefix match','VPC route + SG bhi zaroori']}},
    {say:'Reply wapas: orders API → TGW. Ab prod attachment ki table rt-prod decide karti hai. rt-prod mein 192.168.10.0/24 → VPN attachment (BGP se propagated) hai.',flows:[{from:'ec2',to:'tgw',label:'reply',tone:'ok'}],nodes:{tgw:{tone:'ok',badge:'rt-prod'}},panels:{rt:['rt-prod: 192.168.10.0/24 → VPN (propagated)'],why:['Reply ki table alag hai']},ask:Q('Agar rt-prod mein on-prem ka route na hota, toh kya hota?','Request pahunch jaata par reply TGW par drop ho jaata — conversation ke liye dono tables mein route chahiye',['Kuch farak nahi padta, kyunki TGW stateful hai aur reply ko apne aap usi tunnel se wapas bhej deta hai','Reply internet gateway se nikal jaata, kyunki missing route par AWS default internet path use karta hai','Request bhi kabhi pahunchta hi nahi, kyunki forward hop ke liye bhi rt-prod ki entry padhi jaati hai'],0,'TGW routing stateless hai: reply ek naya routing decision hai jo prod attachment ki table (rt-prod) leti hai. Forward hop rt-onprem se hua tha. Missing route par koi default internet path nahi milta.')},
    {say:'DNS: warehouse app orders.shopkaro.internal resolve karta hai. On-prem DNS forwarder query ko shared VPC ke Resolver inbound endpoint IPs par bhejta hai; private hosted zone se jawab aata hai.',flows:[{from:'onprem',to:'vpn',label:'IPsec',tone:'ok'},{from:'vpn',to:'tgw',tone:'ok'},{from:'tgw',to:'r53',label:'DNS',tone:'ok'}],nodes:{r53:{tone:'ok',badge:'2 IPs, 2 AZs'}},panels:{rt:['rt-onprem: 10.30.0.0/16 → shared'],why:['Inbound = on-prem → AWS names','Outbound + rule = AWS → godam.local']}},
    {say:'Dev isolation check: dev apps se 10.10.0.0/16 ka packet rt-dev mein static blackhole par drop hota hai. Dev ko sirf shared services milte hain.',flows:[{from:'ec2#dev',to:'tgw',label:'blocked',tone:'bad'}],nodes:{'ec2#dev':{tone:'bad',badge:'dev ↛ prod'}},panels:{rt:['rt-dev: 10.10.0.0/16 → blackhole (static)','rt-dev: 10.30.0.0/16 → shared'],why:['Static same prefix par propagated se pehle']},ask:Q('Same table mein static blackhole 10.10.0.0/16 aur propagated 10.10.0.0/16 dono hon, toh kaun jeetega?','Static route — same prefix par static ko priority milti hai, isliye blackhole guardrail kaam karta hai',['Propagated route — BGP se aaya route hamesha static configuration ko override kar deta hai','Jo route baad mein bana — TGW same prefix ke routes mein sabse naye route ko chunta hai','Dono mein load balancing — TGW ECMP se aadha traffic drop aur aadha prod bhejta hai'],0,'AWS docs: same destination par static route ki priority zyada hai, isliye propagated route table mein dikhta hi nahi. ECMP alag attachment types mein nahi hota; creation time decide nahi karta.')},
    {say:'Data path tayyar: on-prem ↔ prod/shared, dev isolated. DX aane par transit VIF aur DX gateway isi TGW par judte hain; VPN backup ban jaata hai.',nodes:{tgw:{tone:'ok',badge:'4 tables'},vpn:{tone:'idle',badge:'backup later'}},panels:{rt:['Har flow: forward table + return table'],why:['DX baad mein primary, VPN backup']}}
   ]},
   {type:'flowlab',title:'🎛️ Link planner — week 3 aur month 4',goal:'Week 3: ≥ 2 Gbps encrypted link ready. Month 4: ≥ 5 Gbps consistent, encrypted, ek link fail hone par bhi chale. Hybrid DNS aur dev isolation zaroori. Budget ₹1,70,000/month. Start: kuch nahi abhi, VPN hi aage, no encryption add-on, no DNS, flat table.',scenario:'Course model: hafte aur rupees declared planning assumptions/fictional quotes hain, AWS prices ya SLAs nahi. VPN standard tunnel up to 1.25 Gbps; 2 VPN connections + BGP = 4 tunnels ECMP (planning 5 Gbps, internet par consistent nahi). DX ko hafte lagte hain, default encrypted nahi.',knobs:[{id:'now',label:'Week 3 link',min:0,max:3,step:1,value:0,labels:{0:'Kuch nahi — DX ka intezaar',1:'1 VPN, static routes',2:'2 VPN connections + BGP (ECMP)',3:'Dedicated DX abhi order'}},{id:'later',label:'Month 4 link',min:0,max:3,step:1,value:0,labels:{0:'VPN hi chalne do',1:'Hosted DX 2 Gbps',2:'Dedicated 10G DX + VPN backup',3:'2 dedicated DX, 2 locations'}},{id:'encrypt',label:'DX par encryption',min:0,max:1,step:1,value:0,labels:{0:'Kuch nahi',1:'VPN over DX / MACsec'}},{id:'dns',label:'Hybrid DNS',min:0,max:1,step:1,value:0,labels:{0:'Hard-coded IPs',1:'Resolver inbound + outbound'}},{id:'segment',label:'TGW route tables',min:0,max:1,step:1,value:0,labels:{0:'Ek flat table',1:'Alag tables + blackhole'}}],model:k=>{const m=planner(k),tone=ok=>ok?'ok':'bad';return {readouts:[{label:'Week 3',value:m.week3?'Ready: '+NOW[k.now].gbps+' Gbps encrypted':'Fail',tone:tone(m.week3)},{label:'Month 4',value:m.month4?LATER[k.later].gbps+' Gbps, consistent, resilient, encrypted':'Fail',tone:tone(m.month4)},{label:'Hybrid DNS',value:k.dns?'Names resolve both ways':'IPs hard-coded',tone:tone(k.dns===1)},{label:'Segmentation',value:k.segment?'dev isolated':'flat: sab sabse baat',tone:tone(k.segment===1)},{label:'Monthly kharch (fictional quotes)',value:inr(m.cost)+' / '+inr(BUDGET),tone:tone(m.cost<=BUDGET)}],bars:[{label:'Kharch vs budget',pct:Math.min(100,Math.round(m.cost/BUDGET*100)),tone:tone(m.cost<=BUDGET),text:inr(m.cost)}],verdict:{ok:m.ok,text:m.ok?'Saare contracts fit: abhi 2 VPN + BGP, baad mein 10G DX + VPN backup. Asli bandwidth aur failover test se confirm karo.':'Abhi fail: '+m.fails.join('; ')+'.'}};},check:k=>planner(k).ok,lesson:'Week 3 ke liye sirf VPN ready hota hai, aur 2 Gbps ke liye BGP + ECMP chahiye. Month 4 ke liye 10G DX + VPN backup consistent aur resilient hai; do locations wala DX zyada resilient par budget todta hai. DX par encryption alag se jodo. DNS aur segmentation design ka hissa hain, baad ki cheez nahi.'},
   {type:'bins',title:'Requirement → hybrid tool',instructions:'Har requirement ko sahi tool mein daalo.',bins:[{id:'vpn',label:'🔒 Site-to-Site VPN'},{id:'dx',label:'🔗 Direct Connect'},{id:'tgw',label:'🕸️ Transit Gateway'},{id:'resolver',label:'🧭 Resolver endpoint'}],items:[{text:'GodamTech ko 3 din mein encrypted connectivity chahiye',bin:'vpn',explain:'VPN din mein ban jaata hai aur IPsec encrypted hai. DX ko hafte lagte hain.'},{text:'Roz 4 TB inventory sync, stable latency, private line',bin:'dx',explain:'Bada, consistent traffic = Direct Connect. Internet VPN ka bandwidth unpredictable hai.'},{text:'Kai VPCs aur on-prem ko ek hub se jodna, segmentation ke saath',bin:'tgw',explain:'Transit Gateway hub hai; alag route tables segmentation dete hain.'},{text:'On-prem servers ko orders.shopkaro.internal resolve karna hai',bin:'resolver',explain:'Inbound endpoint on-prem DNS queries ko VPC Resolver tak laata hai.'},{text:'AWS apps ko godam.local naam resolve karne hain',bin:'resolver',explain:'Outbound endpoint + forwarding rule on-prem DNS ko query bhejta hai.'},{text:'DX gire toh sasta backup path',bin:'vpn',explain:'DX + VPN backup ek common, sasta resiliency model hai (kam bandwidth par).'},{text:'Prod aur dev ek doosre se baat na karein, par dono shared services use karein',bin:'tgw',explain:'Alag route tables: dev table mein prod route nahi (blackhole), shared table sabko jaanti hai.'}]},
   {type:'order',title:'🧭 Direct Connect setup — sahi order',instructions:'Transit VIF wale DX ke steps kram mein lagao.',steps:[{text:'Bandwidth, location aur partner/colocation decide karo',explain:'Pehle requirement aur location; partner circuit ka kaam bhi hafte leta hai.'},{text:'AWS mein connection request (port speed) karo',explain:'Dedicated port speed baad mein badal nahi sakti. Review mein 72 business hours tak lag sakte hain.'},{text:'LOA-CFA download karke provider ko do',explain:'LOA-CFA ke bina cross-connect order nahi hota.'},{text:'Provider DX location par cross-connect lagata hai',explain:'Physical link ab judta hai; billing port active hone par (ya LOA ke 90 din baad).'},{text:'Transit VIF banao aur DX gateway se jodo',explain:'Transit VIF DX gateway ke through Transit Gateway tak jaata hai.'},{text:'DX gateway ko Transit Gateway se associate karo (allowed prefixes)',explain:'Kaunse prefixes on-prem ko advertise honge, yahin tay hota hai.'},{text:'BGP up, routes check, VPN ko backup rakho aur failover test karo',explain:'Failover test ke bina resiliency sirf kaagaz par hai.'}]},
   {type:'triage',title:'🩺 "Dev VPC prod DB tak pahunch raha hai!"',symptom:'Security audit: dev VPC ke ek server se prod DB (10.10.20.15:5432) par connection ban gaya. Kisi ne kal "testing ke liye" TGW mein kuch badla tha.',goal:'Route tables ki associations aur propagations padhkar asli wajah dhoondho.',commands:[{cmd:`aws ec2 get-transit-gateway-route-table-associations --transit-gateway-route-table-id ${RT_SHARED}`,out:`Associations: ${A_SHARED} (shared VPC), ${A_DEV} (dev VPC)`,clue:true,note:'Dev attachment rt-shared se associated hai — wahi table jisme prod ka route hai.'},{cmd:`aws ec2 search-transit-gateway-routes --transit-gateway-route-table-id ${RT_SHARED} --filters Name=state,Values=active`,out:'10.10.0.0/16 → prod (propagated) · 10.20.0.0/16 → dev (propagated) · 192.168.10.0/24 → VPN (propagated)',clue:true,note:'rt-shared sabko jaanti hai (shared ke liye sahi), par dev ke liye galat table.'},{cmd:`aws ec2 get-transit-gateway-route-table-propagations --transit-gateway-route-table-id ${RT_PROD}`,out:`Propagations: ${A_SHARED} (enabled), ${A_VPN} (enabled), ${A_DEV} (enabled)`,clue:true,note:'rt-prod mein dev propagation on hai — reply path bhi khul gaya.'},{cmd:'aws ec2 describe-security-groups --group-ids sg-0prodb0000000001',out:'Inbound 5432 from 10.0.0.0/8',clue:false,note:'SG bahut broad hai — alag se tight karo, par routing hi root cause hai.'},{cmd:`aws ec2 describe-route-tables --filters Name=vpc-id,Values=${VPC.dev.id}`,out:'10.20.0.0/16 local · 10.0.0.0/8 → tgw-0shop0000000001',clue:false,note:'VPC se TGW ka route normal hai; faisla TGW tables mein hota hai.'}],questions:[Q('Dev prod tak kyun pahunch raha hai?','Dev attachment rt-shared se associated hai (prod route ke saath) aur rt-prod mein dev propagation on hai',['Prod security group 10.0.0.0/8 allow karta hai, isliye TGW routing ka is mein koi role nahi','Dev VPC ki subnet route table mein 10.0.0.0/8 → TGW hai, isliye TGW sab tables ignore karta hai','VPN attachment dev aur prod ko bridge kar raha hai, kyunki on-prem routes sab tables mein hain'],0,'Forward: dev ki table (rt-shared) mein prod route. Return: rt-prod mein dev route. Dono milkar conversation kholte hain. SG broad hai par routing ke bina packet pahunchta hi nahi; VPN dev se juda nahi hai.'),Q('Sahi fix kya hai, jo baaki connectivity na tode?','rt-prod se dev propagation hatao, dev ko rt-shared se disassociate karke rt-dev par associate karo',['rt-shared se prod aur dev dono propagations hata do, taaki shared table kisi ko na jaane','TGW delete karke naya banao, kyunki associations badalne ka koi supported tareeka nahi hai','Dev attachment ko rt-prod se bhi associate kar do, taaki dev ki do tables ho jayein'],1,'Dev ko apni table (shared route + prod blackhole) par lao aur prod ka reply path band karo. rt-shared ki propagations hatane se shared services tootengi; attachment ek hi table se associate ho sakta hai; TGW rebuild ki zaroorat nahi.')]},
   {type:'terminal',title:'🖥️ GodamTech VPN — sahi route tables ke saath',instructions:'In-app hybrid fixture (Mumbai). Sirf routing metadata; IPsec/BGP session aur asli packets nahi chalte.',goal:'<p><b>1.</b> Network team ne GodamTech ka customer gateway <code>'+CGW+'</code> bana diya hai (BGP ASN 65010). Transit Gateway <code>'+TGW+'</code> par <code>ipsec.1</code> VPN banao (default dynamic/BGP routing). VPN pending se available hone tak <code>vpn-connection-available</code> waiter chalao. Naya VPN aur attachment ID output mein milega.</p><p><b>2.</b> VPN attachment ko khaali <code>rt-onprem</code> ('+RT_ONPREM+') se associate karo. rt-onprem mein prod aur shared attachments ki propagation on karo (on-prem → prod/shared).</p><p><b>3. Return path:</b> rt-prod ('+RT_PROD+') aur rt-shared ('+RT_SHARED+') mein VPN attachment ki propagation on karo. rt-dev ko mat chhedo — dev ko on-prem nahi milna chahiye. Aakhir mein <code>search-transit-gateway-routes</code> se rt-onprem ke active routes padho — wahi final action hai.</p><p>8 actions. TGW, VPC attachments, CGW aur baaki tables original rahen. Flat table, dev tak on-prem route, extra route table ya deleted VPN jeet nahi dilayega. Static-routing VPN bhi chal sakta hai agar tum khud static routes daalo.</p>',account:seed(),tasks,solution,hints:['Pehle describe-transit-gateway-route-tables aur get-transit-gateway-route-table-propagations se current design padho. Har flow ke liye forward aur return table socho.',solution.slice(0,2).join(' phir '),solution.slice(2,5).join(' phir '),solution.slice(5).join(' phir ')],success:AG.allOf(tasks),successText:'GodamTech VPN available aur rt-onprem par. On-prem ↔ prod/shared dono taraf routes, dev isolated. Agla asli kaam: tunnels/BGP health ka monitoring, Resolver endpoints, DX order aur failover test — simulator in cheezon ko prove nahi karta.'},
   {type:'docker',title:'🐳 Lab24 — TGW segments aur hybrid DNS metadata',project:'24-hybrid-tgw-segments',goal:'Apna khud ka Moto server chalao, TGW route tables aur Resolver config banao, aur dekho Moto kahan asli AWS se alag hai.',why:'Moto association/propagation metadata store karta hai, par propagated routes search mein nahi dikhata aur ek attachment ko do tables se associate hone deta hai. Lab ek documented route evaluator se asli rule bhi dikhata hai.',steps:[{text:'aws-gurukul folder se README aur lab.py padho, phir lab chalao.',cmd:'./docker-labs/.venv/bin/python -I docker-labs/24-hybrid-tgw-segments/lab.py',expect:'Behavior checks + cleanup, phir OWNED MOTO STOPPED / LISTENER CLOSED.'},{text:'SEARCH aur DOUBLE ASSOCIATION lines dekho.',expect:'Propagated routes Moto search mein nahi aate; do tables se association accept ho jaata hai — asli AWS mein ek hi table allowed.'},{text:'EVALUATOR matrix padho.',expect:'Asli Moto metadata se documented rules (longest prefix, static > propagated, return path) lagakar reachability matrix — dev ↛ prod.'}],observe:Q('Lab24 se kya sach mein prove hua?','Moto mein TGW/VPN/Resolver metadata bana; reachability documented evaluator se nikli, packets se nahi',['Moto ne asli IPsec tunnels aur BGP session chala kar on-prem routes TGW mein propagate kar diye','Moto ne double association reject karke prove kiya ki attachment sirf ek table se judta hai','Moto search ne propagated routes dikha diye, isliye AWS jaisa routing behaviour poora test ho gaya'],2,'Metadata asli API calls se bana, par Moto ne double association accept ki aur propagated routes search mein nahi dikhaye. Reachability matrix documented rules ka evaluator hai — koi packet, IPsec ya BGP nahi chala.')},
   {type:'quiz',title:'🎓 Hybrid decisions — SAA aur real job',questions:[
    Q('GodamTech ko abhi 3 Gbps encrypted chahiye. Ek VPN connection, static routing kaafi hai?','Nahi: standard tunnel up to 1.25 Gbps; BGP ke saath ECMP se kai tunnels/connections jodo (ya large-bandwidth tunnel)',['Haan: ek VPN connection ke dono tunnels static routing mein bhi hamesha milkar 2.5 Gbps se upar dete hain','Haan: VPN ki bandwidth sirf on-prem internet speed par depend karti hai, AWS side par koi limit nahi hai','Nahi: VPN 100 Mbps se upar kabhi nahi jaata, isliye Direct Connect ke bina koi raasta nahi bachta'],3,'AWS quotas: standard tunnel up to 1.25 Gbps, large-bandwidth tunnel up to 5 Gbps. TGW par ECMP sirf dynamic (BGP) routing ke saath; static routing par ECMP nahi.'),
    Q('Compliance encryption in transit maangta hai. Traffic Direct Connect par jaayega. Kya karein?','DX default encrypted nahi: select dedicated ports par MACsec, ya DX ke upar IPsec VPN chalao',['Kuch nahi: DX private physical line hai, isliye AWS default se har frame encrypt karta hai','Public VIF lagao: public VIF par traffic apne aap TLS se encrypt ho jaata hai, app ko kuch nahi karna','Hosted connection lo: partner ki policing har packet ko encrypt bhi karti hai, isliye compliance ho jaata hai'],0,'DX private hai par encrypted nahi. MACsec select dedicated connections par layer-2 encryption deta hai; VPN over DX IPsec deta hai. VIF type ya hosted policing encryption nahi hai.'),
    Q('Connectivity 5 din mein chahiye; Direct Connect abhi order hua hai. Plan?','Site-to-Site VPN se shuru karo; DX ready hone par DX primary aur VPN backup rakho',['DX ko expedite karo — AWS 5 din ke andar dedicated port, LOA aur cross-connect sab guarantee karta hai','VPC peering on-prem ke saath banao — peering din mein ban jaata hai aur encrypted bhi hota hai','Deadline 3 mahine aage karo — VPN production ke liye kabhi supported nahi hota, sirf test ke liye'],1,'DX mein port review, LOA-CFA aur provider cross-connect lagta hai — hafte. VPN din mein ban jaata hai. Peering sirf VPCs ke beech hota hai; VPN production mein common hai, khaaskar backup ke roop mein.'),
    Q('Ek TGW attachment ko do route tables se associate karna hai. Kya hoga?','Possible nahi: attachment exactly ek table se associate hota hai; propagation kai tables mein ho sakti hai',['Possible hai: TGW dono tables ke routes merge karke sabse lambe prefix se next hop chunta hai','Possible hai: pehli table forward ke liye aur doosri table reply ke liye apne aap use hoti hai','Possible nahi: attachment kisi table se associate hi nahi hota, sirf propagation hoti hai'],2,'AWS docs: each attachment can be associated with one route table, aur ek attachment kai tables mein propagate kar sakta hai. Reply destination attachment ki apni table se hota hai.'),
    Q('On-prem servers ko DX/VPN se S3 private chahiye. Gateway endpoint kaam karega?','Nahi: gateway endpoint on-prem traffic serve nahi karta; S3 interface endpoint (PrivateLink) use karo',['Haan: gateway endpoint ka prefix-list route on-prem tak BGP se apne aap advertise hota hai','Haan: bas S3 bucket policy mein on-prem IP range allow karo, gateway endpoint baaki sambhal lega','Nahi: on-prem se S3 hamesha sirf public internet se jaata hai, koi private option exist nahi karta'],3,'Gateway endpoints sirf VPC ke andar ke traffic ke liye hain. Interface endpoint VPC mein private IP deta hai jo VPN/DX se reachable hai. Public internet ke alawa private option exist karta hai.'),
    Q('On-prem apps ko AWS private hosted zone ke naam (orders.shopkaro.internal) resolve karne hain. Kya banayein?','Resolver inbound endpoint; on-prem DNS se us domain ki queries inbound endpoint IPs par forward karo',['Resolver outbound endpoint; outbound endpoint on-prem queries ko VPC ke andar private zones tak laata hai','Public hosted zone; private zone ke records copy karke internet par publish karna sabse simple tareeka hai','VPC peering on-prem ke saath; peering hote hi private hosted zones apne aap on-prem par visible ho jaate hain'],0,'Inbound endpoint on-prem → VPC queries ke liye hai. Outbound ulti disha (VPC → on-prem) ke liye. Private records public karna leak hai; peering on-prem ke saath hota hi nahi.'),
    Q('Same TGW table mein static 10.10.0.0/16 blackhole aur propagated 10.10.0.0/16 hai. Traffic ka kya hoga?','Drop hoga: same prefix par static route ki priority zyada hai, isliye blackhole jeetta hai',['Prod jaayega: propagated route BGP se aata hai, isliye static configuration ko override kar deta hai','Aadha-aadha: TGW ECMP se dono routes mein load balance karta hai, aadha drop aur aadha prod','Error aayega: TGW ek hi prefix ke do routes accept nahi karta aur dono routes inactive ho jaate hain'],1,'AWS docs: static aur propagated same destination par static ki priority; propagated route table mein include nahi hota. Isliye blackhole guardrail ka kaam karta hai.'),
    Q('Ek DX se Mumbai aur Hyderabad dono Regions ke Transit Gateways tak jaana hai. Kya design?','Transit VIF ko Direct Connect gateway se jodo aur DX gateway ko dono Regions ke TGWs se associate karo',['Har Region ke liye alag physical DX connection zaroori hai, kyunki DX hamesha ek hi Region tak simit hai','Public VIF lagao aur internet ke through dono Regions ke TGW public endpoints tak traffic bhejo','Mumbai TGW ko Hyderabad VPCs se seedha attach karo, kyunki TGW attachments Region boundary ignore karte hain'],2,'DX gateway global resource hai jo transit VIF ko kai Regions ke TGWs se jodta hai. TGW attachments regional hain; public VIF private hybrid routing ke liye nahi hai.')
   ]}
  ],
  interview:{title:'Interview — hybrid design aur segmentation repair',instructions:'Chaar faisle, phir dev isolation bug theek karo.',questions:[
   Q('Payments ka critical workload DX par hai. Maximum resiliency ka design?','Do alag DX locations par alag connections, har location par redundant devices, aur failover test',['Ek DX location par ek connection aur ek VPN backup, kyunki VPN backup hamesha same bandwidth deta hai','Ek hi DX connection par LAG bana do, kyunki LAG location failure se bhi poori tarah bacha leta hai','Hosted connection lo, kyunki partner ka network har failure ko AWS ki taraf se automatically sambhalta hai'],3,'Location failure se bachne ke liye connections alag DX locations par chahiye. DX + VPN backup sasta hai par bandwidth girti hai; ek location ka LAG location failure se nahi bachata.'),
   Q('Partner SaaS ko apni API privately deni hai; dono ke VPC CIDRs overlap karte hain. Kya chunoge?','PrivateLink endpoint service (NLB ke peeche); partner apne VPC mein interface endpoint banata hai',['VPC peering, kyunki overlapping CIDRs peering mein apne aap translate ho jaate hain','Transit Gateway, kyunki TGW route tables overlapping CIDRs ko alag rakh kar route kar dete hain','Public ALB, kyunki overlap problem sirf private networking mein hoti hai, internet par nahi'],0,'PrivateLink poora network nahi jodta, sirf ek service expose karta hai, isliye overlap chalta hai. Peering aur TGW overlapping CIDRs route nahi kar sakte; public ALB private requirement todta hai.'),
   Q('VPC-to-VPC aur egress traffic central firewall se inspect karna hai. Design?','Inspection VPC mein AWS Network Firewall (ya GWLB + appliances), TGW tables us VPC se route karein, appliance mode on',['Har instance par host firewall lagao — central inspection ki zarurat nahi, aur TGW tables waise hi rahen','Security groups mein deny rules likho — SG stateful firewall hai aur central inspection ka replacement hai','NACLs har subnet par lagao — NACL deep packet inspection karta hai aur central appliance ki zarurat khatam'],1,'Central inspection = inspection VPC + TGW routing; stateful appliances ke liye appliance mode symmetric path rakhta hai. SG allow-only hai, NACL stateless L3/L4 hai — dono deep inspection nahi.'),
   Q('Sirf 2 VPCs ko jodna hai, transitive routing ya on-prem nahi. Sasta aur simple?','VPC peering: do VPCs ke liye simple aur sasta; TGW kai VPCs ya hybrid hub ke liye',['Transit Gateway: hamesha sasta hai kyunki attachment ka koi hourly kharch nahi hota','Direct Connect: do VPCs ko jodne ka sabse sasta tareeka private line hi hai','Site-to-Site VPN: dono VPCs ke beech IPsec sabse simple aur free option hai'],2,'Do VPCs bina transitive zarurat ke → peering. TGW per-attachment-hour + processing kharch leta hai; DX aur VPN on-prem connectivity ke liye hain.'),
   {terminal:{type:'terminal',title:'🖥️ Repair: dev ko wapas rt-dev par lao',instructions:'Kal ki "testing" ne segmentation tod diya. VPN aur on-prem routes sahi hain — VPN aur on-prem routes ko mat chhedo.',goal:'<p>Dev attachment <code>'+A_DEV+'</code> galti se rt-shared ('+RT_SHARED+') se associated hai, aur rt-prod ('+RT_PROD+') mein dev propagation on hai. rt-prod se dev propagation band karo, dev ko rt-shared se disassociate karo, phir rt-dev ('+RT_DEV+') se associate karo. Aakhir mein rt-dev ke active + blackhole routes padho.</p><p>4 actions. rt-dev ka shared propagation aur prod blackhole pehle se hai. VPN/on-prem routes, shared table aur VPC attachments original rahen. Attachment ek hi table se associate hota hai — pehle disassociate.</p>',account:seed('broken'),tasks:itasks,solution:isolution,hints:['Do bugs hain: dev ki galat association (forward path) aur rt-prod ki dev propagation (return path).',isolution.slice(0,3).join(' phir '),isolution[3]],success:AG.allOf(itasks),successText:'Dev wapas rt-dev par: shared mil raha hai, prod blackhole par. rt-prod ka dev route hata. VPN aur on-prem routes unchanged. Asli network mein agla kaam: flow logs se verify, prod DB ka SG tight karna aur change review.'}}
  ]},
  success:['Deadline, bandwidth aur encryption se VPN vs DX (aur resiliency model) choose kar sakta hoon.','TGW route tables mein association, propagation, blackhole aur return path design/debug kar sakta hoon.','Hybrid DNS, on-prem S3 access aur PrivateLink/inspection ke sahi tools bata sakta hoon.'],
  homework:'<p>Optional, real AWS — approval aur cost review ke baad. Ek test account mein do chhote VPCs (non-overlapping CIDRs) aur ek Transit Gateway banao, default association/propagation band. Do route tables banao aur VPC A ko table A, VPC B ko table B se associate karo. Pehle sirf ek taraf propagation on karo aur EC2 ping se dekho reply kyun drop hota hai; phir doosri taraf bhi on karo. Cleanup: attachments, route tables, TGW aur VPCs delete karo — TGW attachments per hour bill hote hain. VPN ya DX practice ke liye alag approval lo.</p>',
  cards:[{front:'VPN tunnel bandwidth?',back:'Standard tunnel up to 1.25 Gbps (large-bandwidth option up to 5 Gbps). Har VPN = 2 tunnels. TGW par ECMP ke liye BGP (dynamic routing) chahiye.'},{front:'DX dedicated vs hosted?',back:'Dedicated: 1/10/100/400 Gbps, ek customer ka port, speed fixed. Hosted: partner provision, 50 Mbps–25 Gbps, partner speed badal sakta hai, traffic policing.'},{front:'DX encrypted?',back:'Nahi, default nahi. MACsec (select dedicated ports) ya DX ke upar IPsec VPN.'},{front:'DX resiliency models?',back:'Single DX = SPOF. DX + VPN backup = sasta, degraded. 2 connections ek location = device failure. Alag locations = location failure bhi (critical).'},{front:'TGW association vs propagation?',back:'Association: attachment kaunsi table padhega (exactly ek). Propagation: attachment ke routes kin tables mein dikhen (kai). Reply destination ki table se.'},{front:'Static vs propagated (same prefix)?',back:'Static jeetta hai; propagated table mein include nahi hota. Isliye static blackhole guardrail kaam karta hai.'},{front:'Resolver inbound vs outbound?',back:'Inbound: on-prem → AWS names (private hosted zones). Outbound + forwarding rule: AWS → on-prem domains. Har endpoint 2+ IPs.'},{front:'On-prem se S3 private?',back:'S3 interface endpoint (PrivateLink). Gateway endpoint sirf VPC ke andar ke traffic ke liye — on-prem/TGW/peering se nahi.'}]
 }]);
})();
